--
-- Name: parcels_default_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parcels_default_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- an empty status is 'registered'; the depot's scan sets the next one
    IF NEW.status = '' THEN
        NEW.status := 'registered';
    END IF;
    RAISE DEBUG 'parcel %: status %; label ''%''', NEW.tracking_number, NEW.status, $$as printed$$;
    RETURN NEW;
END;
$_$;


