--
-- Name: parcels_in_transit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.parcels_in_transit AS
 SELECT p.id,
    p.tracking_number,
    c.full_name AS courier
   FROM ((public.parcels p
     JOIN public.deliveries d ON ((d.parcel_id = p.id)))
     LEFT JOIN public.couriers c ON ((c.id = d.courier_id)))
  WHERE (p.status = 'in_transit'::text);


